544  int bam_read1(BGZF *fp, bam1_t *b)
   545  {
   546      bam1_core_t *c = &b->core;
   547      int32_t block_len, ret, i;
   548      uint32_t x[8], new_l_data;
   549
   550      b->l_data = 0;
   551
   552      if ((ret = bgzf_read(fp, &block_len, 4)) != 4) {
   553          if (ret == 0) return -1; // normal end-of-file
   554          else return -2; // truncated
   555      }
   556      if (fp->is_be)
   557          ed_swap_4p(&block_len);
   558      if (block_len < 32) return -4;  // block_len includes core data
   559      if (bgzf_read(fp, x, 32) != 32) return -3;
   560      if (fp->is_be) {
   561          for (i = 0; i < 8; ++i) ed_swap_4p(x + i);
   562      }
   563      c->tid = x[0]; c->pos = (int32_t)x[1];
   564      c->bin = x[2]>>16; c->qual = x[2]>>8&0xff; c->l_qname = x[2]&0xff;
   565      c->l_extranul = (c->l_qname%4 != 0)? (4 - c->l_qname%4) : 0;
   566      c->flag = x[3]>>16; c->n_cigar = x[3]&0xffff;
   567      c->l_qseq = x[4];
   568      c->mtid = x[5]; c->mpos = (int32_t)x[6]; c->isize = (int32_t)x[7];
   569
   570      new_l_data = block_len - 32 + c->l_extranul;
   571      if (new_l_data > INT_MAX || c->l_qseq < 0 || c->l_qname < 1) return -4;
   572      if (((uint64_t) c->n_cigar << 2) + c->l_qname + c->l_extranul
   573          + (((uint64_t) c->l_qseq + 1) >> 1) + c->l_qseq > (uint64_t) new_l_data)
   574          return -4;
   575      if (realloc_bam_data(b, new_l_data) < 0) return -4;
   576      b->l_data = new_l_data;
   577
   578      if (bgzf_read(fp, b->data, c->l_qname) != c->l_qname) return -4;
   579      for (i = 0; i < c->l_extranul; ++i) b->data[c->l_qname+i] = '\0';
   580      c->l_qname += c->l_extranul;
   581      if (b->l_data < c->l_qname ||
   582          bgzf_read(fp, b->data + c->l_qname, b->l_data - c->l_qname) != b->l_data - c->l_qname)
   583          return -4;
   584      if (fp->is_be) swap_data(c, b->l_data, b->data, 0);
   585      if (bam_tag2cigar(b, 0, 0) < 0)
   586          return -4;
   587
   588      if (c->n_cigar > 0) { // recompute "bin" and check CIGAR-qlen consistency
   589          int rlen, qlen;
   590          bam_cigar2rqlens(c->n_cigar, bam_get_cigar(b), &rlen, &qlen);
   591          if ((b->core.flag & BAM_FUNMAP)) rlen=1;
   592          b->core.bin = hts_reg2bin(b->core.pos, b->core.pos + rlen, 14, 5);
   593          // Sanity check for broken CIGAR alignments
   594          if (c->l_qseq > 0 && !(c->flag & BAM_FUNMAP) && qlen != c->l_qseq) {
   595              hts_log_error("CIGAR and query sequence lengths differ for %s",
   596                      bam_get_qname(b));
   597              return -4;
   598          }
   599      }
   600
   601      return 4 + block_len;
   602  }
